def _add(a, b, mult=1):
    out = dict(a)
    for k, v in b.items():
        out[k] = out.get(k, 0) + v * mult
    return out


def _sub(a, b):
    out = dict(a)
    for k, v in b.items():
        out[k] = out.get(k, 0) - v
    return out


def _ge(a, b):
    for k, v in b.items():
        if a.get(k, 0) < v:
            return False
    return True


def _positive(d):
